catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    // Skip if form is loading or field was cleared
    if (isLoading || newValue === '') {
        return;
    }

    // Clear any stale error messages
    g_form.clearMessages();

    // newValue = the End date/time just entered
    var end = newValue;

    // Fetch current Start value from the form
    var start = g_form.getValue('start_date_time');

    // Compare — string comparison works because
    // ServiceNow uses sortable YYYY-MM-DD HH:mm:ss format
    if (start && end < start) {
        // Clear FIRST, then show message — prevents
        // the re-render from wiping the message
        g_form.clearValue('end_date_time');
        g_form.showFieldMsg('end_date_time',
            'End date/time should not be before the Start date/time', 'error');
    }
}
